with incoming(lemma, kind, sense_id, ordinal, pos, gender, text, example, example_translation) as (values ('ridder', 'word', 'bb0e51ca-1897-53ce-a653-dee2708e4d69', 1, 'noun', 'en', 'knight', 'Ridderen kæmpede tapper i slaget.', 'The knight fought bravely in the battle.'), ('ridder', 'word', '45349a2d-334a-5520-8b6e-dbe62d7b0c40', 2, 'noun', 'en', 'knight of an order (honorary title)', 'Han blev slået til ridder af Dannebrog.', 'He was knighted into the Order of the Dannebrog.'), ('profet', 'word', '1f5ecc3a-4dda-5126-a43a-c4097acfd014', 1, 'noun', 'en', 'prophet', 'Profeten forudsagde krigen.', 'The prophet foretold the war.'), ('pandemi', 'word', 'e3fd6adc-fe45-5655-878d-f498ef126eef', 1, 'noun', 'en', 'pandemic', 'Pandemien ramte hele verden.', 'The pandemic hit the whole world.'), ('effektivitet', 'word', '8aa0d2f7-1612-56ab-98d1-6d2f93fd5b94', 1, 'noun', 'en', 'efficiency', 'Vi vil øge effektiviteten på fabrikken.', 'We want to increase efficiency at the factory.'), ('senat', 'word', '78e7850b-acb0-59cb-8b53-ab4f179b3219', 1, 'noun', 'et', 'senate', 'Senatet stemte om loven.', 'The senate voted on the law.'), ('montere', 'word', '815bf06d-386e-58df-9dde-2a040d233b8e', 1, 'verb', null, 'to install, to mount', 'Vi skal montere den nye lampe.', 'We need to install the new lamp.'), ('værtshus', 'word', '52e85730-f8dd-5d41-aaaf-3c9650cc1117', 1, 'noun', 'et', 'pub, tavern', 'De drak øl på værtshuset.', 'They drank beer at the pub.'), ('iscenesættelse', 'word', '9a7db67d-9b95-519c-b8e4-6b7906d10184', 1, 'noun', 'en', 'staging (of a play), production', 'Iscenesættelsen af stykket var meget moderne.', 'The staging of the play was very modern.'), ('opklare', 'word', '3d260be4-0463-57e1-ae7a-065e8f51b472', 1, 'verb', null, 'to solve (a crime), to investigate', 'Politiet formåede at opklare mordet.', 'The police managed to solve the murder.'), ('deadline', 'word', '60f422cc-c4ad-5701-a14d-57cc7533691c', 1, 'noun', 'en', 'deadline', 'Vi har en deadline i morgen.', 'We have a deadline tomorrow.'), ('atlet', 'word', '6a51a320-90da-5d7e-bb73-a5e235e1a6d8', 1, 'noun', 'en', 'athlete', 'Atleten trænede hver dag.', 'The athlete trained every day.'), ('kynisk', 'word', '17755db8-2ea8-5662-a00d-bb485b8b7ee1', 1, 'adjective', null, 'cynical', 'Han er meget kynisk over for andre.', 'He is very cynical toward others.'), ('lynhurtig', 'word', '7522067c-4478-5287-8b42-c514df597bf5', 1, 'adjective', null, 'lightning-fast, very quick', 'Han gav et lynhurtigt svar.', 'He gave a lightning-fast answer.'), ('tænkning', 'word', '2f31a0a8-38e9-50b2-812d-12b096431e52', 1, 'noun', 'en', 'thinking, thought', 'Hans tænkning er meget logisk.', 'His thinking is very logical.'), ('hæl', 'word', '153cc0f1-2551-5374-9dc8-9074bd44ba4c', 1, 'noun', 'en', 'heel (of the foot)', 'Han har ondt i hælen.', 'His heel hurts.'), ('hæl', 'word', '0e83ab34-6dfe-5f4d-82fa-5dcddb2ec8ba', 2, 'noun', 'en', 'heel (of a shoe)', 'Hendes sko havde en høj hæl.', 'Her shoes had a high heel.'), ('domkirke', 'word', '85b35a8d-2a62-5ea8-a8c4-5e20ded18757', 1, 'noun', 'en', 'cathedral', 'De besøgte domkirken i byen.', 'They visited the cathedral in the city.'), ('facon', 'word', '19ff3451-bbee-510e-b9ae-49fccffc9cdd', 1, 'noun', 'en', 'shape, form; manner', 'Kagen havde en sjov facon.', 'The cake had a funny shape.'), ('scenarie', 'word', 'e6900f50-6953-5db2-8534-4f3c433f9f8e', 1, 'noun', 'et', 'scenario', 'Det værste scenarie er, at vi taber.', 'The worst-case scenario is that we lose.'), ('vicedirektør', 'word', 'd1cc6f07-56f8-5869-8fc8-d0afde7f1c55', 1, 'noun', 'en', 'deputy director', 'Vicedirektøren overtog mødet.', 'The deputy director took over the meeting.'), ('benhård', 'word', 'de733f72-af63-5907-8f28-fd6acab68514', 1, 'adjective', null, 'extremely tough, ruthless', 'Konkurrencen var benhård.', 'The competition was extremely tough.'), ('forgangen', 'word', '551921ba-60a2-5afb-9335-0d39df459d23', 1, 'adjective', null, 'bygone, past', 'Det var en forgangen tid, hvor alt var anderledes.', 'It was a bygone era, when everything was different.'), ('støv', 'word', 'a1886561-9d49-5b3c-bb73-a3668a7da911', 1, 'noun', 'et', 'dust', 'Der er meget støv på hylden.', 'There is a lot of dust on the shelf.'), ('nationalmuseum', 'word', 'aae00c42-708f-5a2a-af67-d1af00b76c1b', 1, 'noun', 'et', 'national museum', 'Danmark har et flot nationalmuseum.', 'Denmark has a fine national museum.'), ('pot', 'word', '233c5072-b636-5af3-b089-7209df5bb4ed', 1, 'noun', null, 'weed, marijuana (informal)', 'Han røg pot i weekenden.', 'He smoked weed over the weekend.'), ('brag', 'word', 'effa3053-d789-5a43-8960-d0706fcd0baa', 1, 'noun', 'et', 'bang, loud crash', 'Der lød et højt brag fra taget.', 'A loud bang sounded from the roof.'), ('udenom', 'word', '8bcb5c26-f6b8-5dbf-9139-9e5161b3ab63', 1, 'adverb', null, 'around, bypassing', 'Vi kørte udenom byen.', 'We drove around the city.'), ('bivirkning', 'word', 'ec27449e-1cdf-53e9-8546-b3fdab5c2c6d', 1, 'noun', 'en', 'side effect', 'Medicinen har en bivirkning.', 'The medicine has a side effect.'), ('genetisk', 'word', 'aa2900d7-d788-5ecc-9886-a8e611906ff1', 1, 'adjective', null, 'genetic', 'Sygdommen er genetisk betinget.', 'The disease is genetically caused.'), ('horn', 'word', 'e9c4e266-2881-56fa-8fb9-329bcd9d5f9e', 1, 'noun', 'et', 'horn (of an animal)', 'Koen har store horn.', 'The cow has big horns.'), ('horn', 'word', '3fa1c53d-325b-506e-a51e-37fc6fcbb655', 2, 'noun', 'et', 'horn, honk (of a car)', 'Han trykkede på hornet.', 'He pressed the horn.'), ('arve', 'word', '5071e65c-b4d1-5979-8b8c-f37e39ef221d', 1, 'verb', null, 'to inherit', 'Hun arvede huset efter sin far.', 'She inherited the house from her father.'), ('diktatur', 'word', 'ff7c3653-4d81-52f3-928f-8ab0621989e8', 1, 'noun', 'et', 'dictatorship', 'Landet levede under et diktatur.', 'The country lived under a dictatorship.'), ('tænkelig', 'word', '69f5ce87-71d8-577a-b299-302224f3adae', 1, 'adjective', null, 'conceivable, possible', 'Det er en tænkelig løsning.', 'It is a conceivable solution.'), ('læring', 'word', '53bf1ac3-ca00-5960-b3a4-b0de8dc286c0', 1, 'noun', 'en', 'learning', 'Læring foregår bedst i trygge rammer.', 'Learning happens best in a safe environment.'), ('embede', 'word', '569e26be-a8e5-51ad-92b1-4293ca3528d1', 1, 'noun', 'et', '(public) office, post', 'Han fik et embede i ministeriet.', 'He got a post in the ministry.'), ('journal', 'word', 'eadb6b59-b947-5b1a-b303-cc3ec47d1e88', 1, 'noun', 'en', 'medical record, log', 'Lægen skrev i journalen.', 'The doctor wrote in the medical record.'), ('islamist', 'word', 'ef1cdf85-7a48-5266-875c-019eb691b8e6', 1, 'noun', 'en', 'Islamist', 'Han blev anklaget for at være islamist.', 'He was accused of being an Islamist.'), ('tankevækkende', 'word', '8981da57-79a7-5027-a682-bac11dda3d37', 1, 'adjective', null, 'thought-provoking', 'Det var en tankevækkende bog.', 'It was a thought-provoking book.'), ('humanistisk', 'word', '657883f7-fa97-5a77-8f3e-84c2b59118e8', 1, 'adjective', null, 'humanities, humanistic', 'Hun læser et humanistisk fag.', 'She is studying a humanities subject.'), ('organisk', 'word', '24358ba6-dfe7-5e26-a539-935b7d74c7ba', 1, 'adjective', null, 'organic', 'De køber organisk mad.', 'They buy organic food.'), ('bedsteforælder', 'word', '9ec011a0-44e4-5051-a03a-6de157e5da80', 1, 'noun', 'en', 'grandparent', 'Hendes bedsteforælder bor på landet.', 'Her grandparent lives in the countryside.'), ('illusion', 'word', '3ad4c6e8-3c26-5187-980a-ca743a189133', 1, 'noun', 'en', 'illusion', 'Det var bare en illusion.', 'It was just an illusion.'), ('beundre', 'word', 'a19fce54-4b0f-5ca6-ae7e-05185e369757', 1, 'verb', null, 'to admire', 'Jeg beundrer hendes mod.', 'I admire her courage.'), ('orientering', 'word', 'e4ff92cd-bda0-522c-93a8-5bfdeb74b8ba', 1, 'noun', 'en', 'briefing, information session', 'Vi fik en kort orientering om sagen.', 'We got a brief briefing on the matter.'), ('orientering', 'word', 'f7fd8f4d-ea7a-5704-8c20-a2995b7e9364', 2, 'noun', 'en', 'orienteering (sport)', 'Han dyrker orientering i skoven.', 'He does orienteering in the forest.'), ('kirkelig', 'word', '969d7640-142c-5a8b-a0d4-b38e6c8d0806', 1, 'adjective', null, 'church, ecclesiastical', 'De holdt en kirkelig vielse.', 'They held a church wedding.'), ('afskedige', 'word', '593f6ec9-3ebe-5436-97ce-aec3ef93d75f', 1, 'verb', null, 'to dismiss, to lay off', 'Firmaet måtte afskedige ti medarbejdere.', 'The company had to lay off ten employees.'), ('blade', 'word', 'f0419fb6-d77e-566e-a33f-f60a248fb92f', 1, 'verb', null, 'to leaf through (pages)', 'Han kan lide at blade i gamle bøger.', 'He likes to leaf through old books.'), ('grundlovsforhør', 'word', '1d0b28b8-4617-5eb3-9ea1-d42c1f21f2b0', 1, 'noun', 'et', 'pre-arraignment hearing (before a judge)', 'Politiet fremstillede den anholdte i grundlovsforhør.', 'The police presented the detainee before the judge for a custody hearing.'), ('indfri', 'word', '3158448c-2fb3-5ab2-9d73-b3992c7a43e8', 1, 'verb', null, 'to fulfil, to keep (a promise)', 'Han indfriede sit løfte til børnene.', 'He kept his promise to the children.'), ('indfri', 'word', 'dd293499-9de4-5f7a-b346-71f178a85bc5', 2, 'verb', null, 'to pay off, to redeem (a debt, a loan)', 'De indfriede lånet efter ti år.', 'They paid off the loan after ten years.'), ('gentagen', 'word', '6ff737da-2f48-5173-8b15-c51ae25ec3e4', 1, 'adjective', null, 'repeated', 'Han fik en gentagen advarsel fra chefen.', 'He received a repeated warning from his boss.'), ('forkorte', 'word', '0dff1a89-0b99-54c6-a09e-c2682935e90f', 1, 'verb', null, 'to shorten', 'Vi måtte forkorte ferien med to dage.', 'We had to shorten the holiday by two days.'), ('udnyttelse', 'word', '64eec919-4cfe-5b9e-a3a8-6c8afb1228cb', 1, 'noun', 'en', 'use, exploitation (of resources)', 'Udnyttelse af solenergi bliver mere almindelig.', 'Use of solar energy is becoming more common.'), ('udnyttelse', 'word', 'a54071b7-3e19-54b7-a7b7-c16f595b87fd', 2, 'noun', 'en', 'exploitation (of people)', 'Fagforeningen kæmper imod udnyttelse af arbejdere.', 'The union is fighting against the exploitation of workers.'), ('udebane', 'word', '55410a67-6f6f-5f3c-a1e9-c17802f53c86', 1, 'noun', 'en', 'away ground (sports)', 'Holdet vandt på udebane i weekenden.', 'The team won away from home over the weekend.'), ('samfundsmæssig', 'word', '537dc024-1887-5ffa-afdc-26bd62547059', 1, 'adjective', null, 'societal, social', 'Uddannelse har stor samfundsmæssig betydning.', 'Education has great societal importance.'), ('betragtelig', 'word', 'cc3062a4-dcf3-5d47-aab7-674a9f585972', 1, 'adjective', null, 'considerable, sizeable', 'Firmaet fik en betragtelig omsætning sidste år.', 'The company had a considerable turnover last year.'), ('undertrykkelse', 'word', '08d17054-869f-52cc-b023-dd3e6c382be5', 1, 'noun', 'en', 'oppression, suppression', 'Folket kæmpede mod undertrykkelse i mange år.', 'The people fought against oppression for many years.'), ('vuggestue', 'word', '8af56574-2599-549a-a482-4bf8d353dca9', 1, 'noun', 'en', 'nursery, crèche', 'Vores søn starter i vuggestue til august.', 'Our son starts nursery in August.'), ('ungarsk', 'word', '345e4147-1f9a-5b48-9144-d507da92371d', 1, 'adjective', null, 'Hungarian', 'Vi spiste ungarsk mad i restauranten.', 'We ate Hungarian food at the restaurant.'), ('stirre', 'word', '6485e38a-c918-57c0-9612-09cef6ea4106', 1, 'verb', null, 'to stare', 'Han sad og stirrede ud af vinduet.', 'He sat staring out of the window.'), ('kulturhus', 'word', '7f29a5f6-e93b-532e-a110-79c3c95519f8', 1, 'noun', 'et', 'cultural centre', 'Der er koncert i kulturhuset på fredag.', 'There is a concert at the cultural centre on Friday.'), ('forværre', 'word', 'd10d1696-523d-5e78-a0b7-a70b3e3a338a', 1, 'verb', null, 'to worsen', 'Regnen forværrede trafiksituationen.', 'The rain worsened the traffic situation.'), ('pil', 'word', '5b542146-8177-5797-99e9-ba9e74378cae', 1, 'noun', 'en', 'arrow (pointer, projectile)', 'Der var en pil, der pegede mod udgangen.', 'There was an arrow pointing toward the exit.'), ('pil', 'word', '53b8108c-a1d7-55de-85c9-4b5195b44d90', 2, 'noun', 'en', 'willow (tree)', 'Der står en gammel pil ved åen.', 'There is an old willow by the stream.'), ('hvorimod', 'word', '9ba478c2-1136-5678-94c7-791604c4ccdf', 1, 'adverb', null, 'whereas', 'Han kan lide te, hvorimod jeg foretrækker kaffe.', 'He likes tea, whereas I prefer coffee.'), ('defensiv', 'word', '3ae790a5-3aea-5e66-9709-5c0f7244333e', 1, 'adjective', null, 'defensive', 'Holdet spillede meget defensivt i anden halvleg.', 'The team played very defensively in the second half.'), ('etik', 'word', 'b1013d60-681e-5d76-a871-8f9f24d82ded', 1, 'noun', 'en', 'ethics', 'Lægerne skal følge en streng etik.', 'Doctors must follow strict ethics.'), ('fiktiv', 'word', '09a0b971-5edf-5f03-829d-d68058678e87', 1, 'adjective', null, 'fictional, fictitious', 'Personerne i romanen er fiktive.', 'The characters in the novel are fictional.'), ('balancere', 'word', '521ff438-be14-501b-a547-7166d4a2ce20', 1, 'verb', null, 'to balance', 'Barnet balancerede på kanten af fortovet.', 'The child balanced on the edge of the pavement.'), ('indsende', 'word', '49105f92-51d9-5a0b-9c45-cfb7f161ef3e', 1, 'verb', null, 'to submit, to send in (an application, documents)', 'Husk at indsende ansøgningen inden fredag.', 'Remember to submit the application by Friday.'), ('mormor', 'word', '38823665-a238-5625-8b9c-70bfc16eb73d', 1, 'noun', 'en', 'grandmother (maternal)', 'Vi besøger mormor hver søndag.', 'We visit grandmother every Sunday.'), ('aktivere', 'word', '02b0f314-2b11-5d69-84bf-f39d875e9794', 1, 'verb', null, 'to activate', 'Du skal aktivere kortet, før du kan bruge det.', 'You need to activate the card before you can use it.'), ('hvortil', 'word', '09038f91-d95b-5d3d-8306-d06a0c4c441a', 1, 'adverb', null, 'to what, for what', 'Hvortil skal disse penge bruges?', 'What is this money to be used for?'), ('konkurrenceevne', 'word', '83ade0a1-a824-5748-8ae1-fba9d7b85e06', 1, 'noun', 'en', 'competitiveness', 'Virksomheden vil styrke sin konkurrenceevne.', 'The company wants to strengthen its competitiveness.'), ('fortov', 'word', '64fc310d-ccdc-59c8-b6ab-827740fa135f', 1, 'noun', 'et', 'pavement, sidewalk', 'Børnene cyklede på fortovet.', 'The children cycled on the pavement.'), ('skadestue', 'word', 'e97a5115-bfe0-54e6-adbe-69d1690eca88', 1, 'noun', 'en', 'emergency room, casualty department', 'Han blev kørt på skadestuen med et brækket ben.', 'He was taken to the emergency room with a broken leg.'), ('forsvarlig', 'word', 'b5fa9b6a-ae57-54a7-87ee-864b71b39475', 1, 'adjective', null, 'proper, responsible, safe', 'Maden skal opbevares på en forsvarlig måde.', 'The food must be stored in a proper manner.'), ('øde', 'word', 'eafe23b4-01a6-5bbc-8058-ad7c8f8f5377', 1, 'adjective', null, 'desolate, deserted', 'De sejlede til en øde ø.', 'They sailed to a desolate island.'), ('genvinde', 'word', '8aed8a33-cbb0-5046-bbf3-c0087b3e0e5f', 1, 'verb', null, 'to regain, to recover', 'Han arbejdede hårdt for at genvinde sit helbred.', 'He worked hard to regain his health.'), ('opfindelse', 'word', 'f8b8fde6-de84-52f2-bfde-0f376a8939e7', 1, 'noun', 'en', 'invention', 'Telefonen var en revolutionerende opfindelse.', 'The telephone was a revolutionary invention.'), ('fleksibilitet', 'word', '9e78f8dd-7acb-5b97-b453-f4c2dd95db5c', 1, 'noun', 'en', 'flexibility', 'Jobbet giver stor fleksibilitet i arbejdstiden.', 'The job offers great flexibility in working hours.'), ('omlægning', 'word', 'ec5602d4-a223-5beb-a405-9d8cdb907a9e', 1, 'noun', 'en', 'restructuring, change (to another system)', 'Der kommer en stor omlægning af skemaet næste år.', 'There will be a big restructuring of the schedule next year.'), ('rygning', 'word', '61fb761f-a057-53a3-b718-9216602b741c', 1, 'noun', 'en', 'smoking', 'Rygning er forbudt på hospitalet.', 'Smoking is forbidden at the hospital.'), ('storebror', 'word', 'b8f73bea-2f57-5be0-9a6a-5903fd80fa1e', 1, 'noun', 'en', 'big brother', 'Min storebr