elcome (of guests)', 'Der var en varm modtagelse ved indgangen.', 'There was a warm reception at the entrance.'), ('modtagelse', 'word', '0d380b7e-3d31-52ae-8148-ff407ef88cca', 2, 'noun', 'en', 'reception (desk, in an office)', 'Aflever papirerne i modtagelsen.', 'Hand in the papers at reception.'), ('asfalt', 'word', '75bd03a7-62e5-5dd8-9140-eca2ab30b94a', 1, 'noun', 'en', 'asphalt', 'Vejen blev dækket med ny asfalt.', 'The road was covered with new asphalt.'), ('statue', 'word', '3b0346cb-7dcc-5b23-b098-1ebc4d7dddf9', 1, 'noun', 'en', 'statue', 'Der står en statue på torvet.', 'There is a statue on the square.'), ('sluge', 'word', '335a9097-fe11-557c-8f51-cea0e18bc255', 1, 'verb', null, 'to swallow, to gulp down', 'Hunden slugte kødet i ét stykke.', 'The dog swallowed the meat in one piece.'), ('formandskab', 'word', 'fe97cb82-5086-55b0-9c80-81836918c4ab', 1, 'noun', 'et', 'chairmanship, presidency', 'Danmark overtager formandskabet i januar.', 'Denmark takes over the chairmanship in January.'), ('ørken', 'word', 'dd8ebffc-a9af-5b79-b937-7c0e03734518', 1, 'noun', 'en', 'desert', 'De kørte i flere dage gennem ørkenen.', 'They drove for several days through the desert.'), ('logo', 'word', '258d18d2-4cbf-5aba-9818-28bf8c2269dd', 1, 'noun', null, 'logo', 'Firmaets logo står på alle bilerne.', 'The company''s logo is on all the vehicles.'), ('nødhjælp', 'word', 'ebc7c57e-8386-5ef4-a444-e665b6162682', 1, 'noun', 'en', 'humanitarian aid', 'Organisationen sender nødhjælp til flygtningene.', 'The organization sends humanitarian aid to the refugees.'), ('kulminere', 'word', 'f06314f1-8f8c-5790-b898-6c57462b188a', 1, 'verb', null, 'to culminate, to peak', 'Konflikten kulminerede i en stor demonstration.', 'The conflict culminated in a large demonstration.'), ('massakre', 'word', '921b54ca-2818-5774-83ca-842157f96a16', 1, 'noun', 'en', 'massacre', 'Byen blev ramt af en frygtelig massakre.', 'The town was hit by a terrible massacre.'), ('komplicere', 'word', 'e72530e2-231c-53b