uthority.'), ('sammenhold', 'word', 'd99b4268-b558-536e-9b84-bccc7d660a39', 1, 'noun', 'et', 'solidarity, cohesion', 'Der er stort sammenhold i familien.', 'There is great solidarity in the family.'), ('manipulere', 'word', '240452a1-8c88-5877-9384-f99812220849', 1, 'verb', null, 'to manipulate', 'Hun følte, at han forsøgte at manipulere hende.', 'She felt he was trying to manipulate her.'), ('kuffert', 'word', '60fa7b06-32c9-50d0-89dc-37569d4e55cf', 1, 'noun', 'en', 'suitcase', 'Han pakkede kufferten aftenen før.', 'He packed the suitcase the evening before.'), ('primitiv', 'word', '59524744-f035-5248-bb81-34dbb726253f', 1, 'adjective', null, 'primitive', 'Værktøjet virkede meget primitivt.', 'The tool seemed very primitive.'), ('ministerpræsident', 'word', '985955fc-e3dd-5061-95a5-0e6c69d37ff1', 1, 'noun', 'en', 'minister-president (of a German state)', 'Ministerpræsidenten mødtes med kansleren.', 'The minister-president met with the chancellor.'), ('polak', 'word', '9f8a4145-4044-5851-b9d9-e0382bf65047', 1, 'noun', 'en', 'Pole (person from Poland)', 'Han er polak og bor nu i Danmark.', 'He is Polish and now lives in Denmark.'), ('dødelig', 'word', 'bc101c48-403c-5487-abfe-b21370a7210f', 1, 'adjective', null, 'deadly, fatal', 'Sygdommen kan være dødelig, hvis den ikke behandles.', 'The disease can be fatal if left untreated.'), ('letbane', 'word', '6082944a-da74-557b-adc5-a18ce531a7e7', 1, 'noun', 'en', 'light rail, tram', 'Letbanen kører gennem hele byen.', 'The light rail runs through the whole city.'), ('samtid', 'word', '14311a45-0d8e-535c-9c28-5b9addc7678e', 1, 'noun', 'en', 'the present, our time', 'Kunstneren skildrer vores samtid.', 'The artist portrays our present.'), ('vaccinere', 'word', '5c6c150e-9d35-56d4-a19c-a3d619f2eb61', 1, 'verb', null, 'to vaccinate', 'Alle børn bliver vaccineret mod mæslinger.', 'All children are vaccinated against measles.'), ('forsvarsministerie', 'word', '242ebe3f-fa1a-593b-99fb-05c88759a129', 1, 'noun', null, 'ministry of defence', 'Forsvarsministerie offentliggjorde nye tal.', 'The ministry of defence released new figures.'), ('gengive', 'word', 'e974fea2-82d7-57f3-9267-5f49e31d0f82', 1, 'verb', null, 'to render, to reproduce (meaning, sound)', 'Højttaleren gengiver lyden meget klart.', 'The speaker reproduces the sound very clearly.'), ('opkræve', 'word', 'f0a80db5-f2eb-5fe0-8c44-2f39d198464e', 1, 'verb', null, 'to charge, to levy (a fee, a tax)', 'Banken opkræver et gebyr for overførslen.', 'The bank charges a fee for the transfer.'), ('event', 'word', 'd8725521-4a86-552e-878c-b08334d8e607', 1, 'noun', null, 'event', 'Der er et stort event i weekenden.', 'There is a big event this weekend.'), ('kendelse', 'word', '4529de83-f379-5b04-9087-e7440f5d9895', 1, 'noun', 'en', 'ruling, verdict (of a court)', 'Retten afsagde en kendelse i sagen.', 'The court issued a ruling in the case.'), ('oversvømmelse', 'word', '7814e487-7518-5851-85ee-1023436447f1', 1, 'noun', 'en', 'flood, flooding', 'Regnen forårsagede en stor oversvømmelse.', 'The rain caused a major flood.'), ('kriger', 'word', 'f61a7647-dbe8-5d84-be0f-00400af5a2b4', 1, 'noun', 'en', 'warrior', 'Han blev hyldet som en sand kriger.', 'He was hailed as a true warrior.'), ('klinge', 'word', 'ab625e4d-8156-5e57-ae68-6bf78bb1a673', 1, 'verb', null, 'to ring, to sound', 'Klokkerne klinger over hele byen.', 'The bells ring across the whole town.'), ('larme', 'word', '85a0eec7-c347-5e21-b5c9-d63360d19be0', 1, 'verb', null, 'to make noise, to be noisy', 'Trafikken larmede hele natten.', 'The traffic was noisy all night.'), ('filial', 'word', '25d00559-8a57-5193-9644-85432c2ac26e', 1, 'noun', 'en', 'branch (of a bank, a company)', 'Banken åbnede en ny filial i byen.', 'The bank opened a new branch in the town.'), ('rinde', 'word', '3e962d89-61db-535e-9e9b-e68fab57c49a', 1, 'verb', null, 'to flow (of water, a river)', 'Åen rinder gennem hele dalen.', 'The stream flows through the whole valley.'), ('udkast', 'word', '9fa47996-990d-5c25-bb1e-0cc136284328', 1, 'noun', 'et', 'draft (of a document)', 'Han skrev et udkast til talen.', 'He wrote a draft of the speech.'), ('hugge', 'word', '998591af-fdd5-5433-a4c9-c37a8308fb1a', 1, 'verb', null, 'to chop (wood)', 'Han huggede brænde til vinteren.', 'He chopped firewood for the winter.'), ('hugge', 'word', '239f9b3f-edf5-5810-ab0e-93750719ba8b', 2, 'verb', null, 'to grab, to sink its claws into', 'Ørnen huggede fisken med sine kløer.', 'The eagle grabbed the fish with its claws.'), ('sno', 'word', '37ea6e90-bb43-5106-be46-8ed49ae0cb75', 1, 'verb', null, 'to wind, to twist, to coil', 'Stien sno sig op ad bjerget.', 'The path winds up the mountain.'), ('indendørs', 'word', 'a034f114-be5f-5a5c-afd4-d79bdd04d4b3', 1, 'adjective', null, 'indoor', 'De spiller fodbold på en indendørs bane.', 'They play football on an indoor pitch.')),
known as (
  select incoming.* from incoming
  where exists (
    select 1 from public.word_catalog_sense existing
    where existing.lemma = incoming.lemma and existing.kind = incoming.kind
      and existing.sense_id = incoming.sense_id::uuid and existing.lang <> 'en'
  )
),
written as (
  insert into public.word_catalog_sense (lemma, kind, sense_id, ordinal, lang, text, pos, gender, example, example_translation, generator)
  select lemma, kind, sense_id::uuid, ordinal, 'en', text, pos, gender, example, example_translation, 'locale-en-2026-09-25' from known
  on conflict (lemma, kind, sense_id, lang) do update set
    text = excluded.text, example = excluded.example, example_translation = excluded.example_translation, generator = excluded.generator
  returning 1
)
select (select count(*) from incoming) as incoming, (select count(*) from known) as matched, (select count(*) from written) as written;
